    /**
     * @description Optionally, authentication token to authenticate at the Connectivity Agent. Prior to the token the authformat has to be specified in the form . For example Bearer {YOUR_TOKEN}
     */
    connectivity_proxy_authentication?: string;
    /**
     * @description Optionally, Location ID as identifier for the SAP Cloud Connector
     */
