    /**
     * @description Specifies whether SNC should be activated for this connection or not. One of the following values:0 SNC off or 1 SNC on
     */
    snc_mode?: 0 | 1;
    /**
     * @description If the connection needs to be made through a firewall via a SAPRouter, specify the SAPRouter parameters in the following format: /H/hostname/S/portnumber
     */
